const sourceType = $json['Source Type'];
const content = ($json['Content'] || '').trim();
const pageUrl = ($json['Page URL'] || '').trim();
const sheetUrl = ($json['Google Sheet URL'] || '').trim();
const hasFile = Boolean($binary && $binary['File'] && $binary['File'].fileName) || Boolean(($json.fileUrl || '').trim());

let valid = false;
let reason = '';

if (sourceType === 'Paste text') {
  valid = content.length > 0;
  reason = 'Source Type is "Paste text" but the Content field is empty.';
} else if (sourceType === 'Website page') {
  valid = /^https?:\/\//.test(pageUrl);
  reason = 'Source Type is "Website page" but Page URL is empty or not a valid http(s) URL.';
} else if (sourceType === 'File (PDF or Word)') {
  valid = hasFile;
  reason = 'Source Type is "File (PDF or Word)" but no file was attached.';
} else if (sourceType === 'Google Sheet') {
  valid = /^https?:\/\/docs\.google\.com\/spreadsheets\//.test(sheetUrl);
  reason = 'Source Type is "Google Sheet" but Google Sheet URL is empty or not a docs.google.com/spreadsheets link.';
} else if (sourceType === 'Google Sheet') {
  valid = true; // connection itself is checked downstream, by Load Sheets Connection
} else if (sourceType === 'Delete Document') {
  valid = true; // no extra fields needed, Customer ID + Document title already validated
} else if (sourceType === 'Monday Board') {
  valid = Boolean(($json.mondayApiToken || '').trim()) && Boolean(($json.mondayBoardId || '').trim());
  if (!valid) reason = 'Monday Board requires mondayApiToken and mondayBoardId';
} else {
  reason = 'Unrecognized Source Type: ' + sourceType;
}

return [{ json: { ...$json, sourceValid: valid, sourceValidationReason: reason } }];

// UPDATED 2026-09-09: previously assumed exactly one document per
// execution via named references, ignoring this node's own input
// entirely. The website crawler can now produce many items (one per
// crawled page), each needing its OWN title -- looping over actual
// input items instead, with a fallback to the old named-reference
// behavior for every other source type, which still sends exactly one
// item with no pageTitle/pageText set.
const customerId = $('Load Customer').item.json.id;
const businessName = $('Load Customer').item.json.business_name;

const MAX_CHARS = 1200;
const OVERLAP = 150;
const MIN_CHUNK = 400; // don't hunt for a boundary so far back that a chunk becomes tiny

// Prefer breaking at a paragraph gap, then a sentence end, then a line break,
// only falling back to a hard character cut if none exist near the target
// size. Added 2026-08-13: the previous version sliced at a fixed character
// count with no regard for word/sentence boundaries, so a price line or
// sentence could be split in half across two chunks, degrading retrieval
// (the model sees half a fact per chunk instead of a whole one).
function findBreakPoint(text, idealEnd) {
  const windowStart = Math.max(MIN_CHUNK, idealEnd - 300);
  const window = text.slice(windowStart, idealEnd);

  const paraBreak = window.lastIndexOf('\n\n');
  if (paraBreak !== -1) return windowStart + paraBreak + 2;

  const sentenceMatch = [...window.matchAll(/[.!?]\s/g)].pop();
  if (sentenceMatch) return windowStart + sentenceMatch.index + sentenceMatch[0].length;

  const lineBreak = window.lastIndexOf('\n');
  if (lineBreak !== -1) return windowStart + lineBreak + 1;

  return idealEnd; // no natural boundary found, hard cut as last resort
}

function chunk(text) {
  const clean = text.replace(/\r\n/g, '\n').trim();
  if (clean.length <= MAX_CHARS) return [clean];

  const chunks = [];
  let start = 0;
  while (start < clean.length) {
    const idealEnd = Math.min(start + MAX_CHARS, clean.length);
    const end = idealEnd === clean.length ? idealEnd : findBreakPoint(clean, idealEnd);
    chunks.push(clean.slice(start, end).trim());
    if (end >= clean.length) break;
    start = Math.max(end - OVERLAP, start + 1); // always advance, even if OVERLAP would otherwise stall on a short boundary
  }
  return chunks;
}

// Guarding with isExecuted rather than a bare || fallback -- n8n statically
// flags any $('NodeName') reference in a Code node's text if that node
// didn't run in the current execution, even when a JS short-circuit would
// have never actually reached it at runtime. isExecuted checks are the
// pattern n8n actually tolerates here.
const results = [];
for (const item of $input.all()) {
  let title, content;
  if (item.json.pageTitle) {
    title = item.json.pageTitle;
    content = item.json.pageText;
  } else {
    title = $('Normalize Ingest Trigger').item.json['Document title'];
    content = $('Merge Content Sources').isExecuted
      ? $('Merge Content Sources').item.json.resolvedContent
      : '';
  }
  const chunks = chunk(content);
  chunks.forEach((text, i) => {
    results.push({
      json: {
        customerId,
        businessName,
        title,
        chunkIndex: i,
        chunkCount: chunks.length,
        text: `${title}\n\n${text}`,
      },
    });
  });
}
return results;

const rows = $input.all().map(item => item.json);
if (rows.length === 0) {
  return [{ json: { resolvedContent: '' } }];
}

const columns = Object.keys(rows[0]).filter(k => k !== 'row_number');

// Flatten each row into a plain-text line, e.g. "Product: Widget | Price: 5000 | Stock: 12"
// rather than dumping raw JSON, since this text is what the AI reads at answer time,
// not parsed as structured data downstream.
const lines = rows.map(row => columns.map(col => `${col}: ${row[col]}`).join(' | '));

return [{ json: { resolvedContent: lines.join('\n') } }];

// Added 2026-08-13. Deliberately not a Merge node here: n8n's Merge node
// modes (chooseBranch, combine/position, etc.) are documented and confirmed
// as fundamentally 2-input concepts, or as waiting on ALL connected inputs
// before proceeding. With 4 branches where only one ever actually produces
// data (the other 3 are dead-end IF branches with zero items), that risks
// either a hang or unpredictable field-merging behavior. Using
// $('NodeName').isExecuted (confirmed safe, does not throw) to check each
// candidate node directly instead, no ambiguity, no wait semantics.
const candidates = [
  'Resolve Content (Paste)',
  'Resolve Content (Website)',
  'Resolve Content (File)',
  'Resolve Content (Sheet)',
];

for (const name of candidates) {
  if ($(name).isExecuted) {
    return [{ json: { resolvedContent: $(name).item.json.resolvedContent } }];
  }
}

throw new Error('Merge Content Sources: none of the 4 Resolve Content branches executed, this should be unreachable given Validate Source Fields already ran.');

// FIXED 2026-09-09: was configured with 'aggregateAllItemStemFields',
// which isn't a real n8n Aggregate mode -- this node has been broken
// since before this file was ever touched this session, just never
// reached in an execution until now. Its only real job is collapsing
// potentially thousands of chunk items down to exactly one, so Update
// Job Status: Success and Respond: Success each run once per job, not
// once per chunk. Neither of those reads this node's actual content --
// both use named references elsewhere -- so a plain single item is
// all that's needed here, nothing more elaborate.
return [{ json: {} }];

// SIMPLIFIED 2026-08-24: KB Upload Form no longer exists (removed for the
// Form Trigger / Respond to Webhook platform conflict). KB Ingest Webhook
// is now the only trigger, so this just builds the flat field shape and
// maps short sourceType values to the internal strings the rest of the
// pipeline expects. No more branching on which trigger fired.

const SOURCE_TYPE_MAP = {
  paste: 'Paste text',
  website: 'Website page',
  file: 'File (PDF or Word)',
  sheet: 'Google Sheet',
  delete: 'Delete Document',
  monday: 'Monday Board',
};

const body = $('KB Ingest Webhook').item.json.body || {};
const sourceType = SOURCE_TYPE_MAP[body.sourceType] || body.sourceType || '';

return [{
  json: {
    'Customer ID': body.customerId || '',
    'Document title': body.documentTitle || '',
    'Source Type': sourceType,
    'Content': body.content || '',
    'Page URL': body.pageUrl || '',
    'Google Sheet URL': body.googleSheetUrl || '',
    fileUrl: body.fileUrl || '',
    mondayApiToken: body.mondayApiToken || '',
    mondayBoardId: body.mondayBoardId || '',
    triggerSource: 'webhook',
  },
  pairedItem: { item: 0 },
}];

const board = $json.data?.boards?.[0];
if (!board) {
  throw new Error('Monday board not found -- check the board ID and that the token has access to it.');
}

const items = board.items_page?.items || [];
const lines = items.map(item => {
  const cols = (item.column_values || [])
    .filter(c => c.text)
    .map(c => c.text)
    .join(' | ');
  return cols ? `${item.name}: ${cols}` : item.name;
});

return [{ json: { resolvedContent: lines.join('\n') } }];

// ADDED 2026-09-02: Create Ingest Job's Postgres output is just
// {id: <job-uuid>} -- it replaced the whole item, dropping Customer ID,
// Document title, Source Type, everything. Every node downstream that
// reads $json['Customer ID'] etc. (Customer ID Looks Valid?, Validate
// Source Fields) was silently getting the wrong data. Re-attaching the
// original fields here fixes it once, at the source, instead of patching
// every downstream node individually.

return [{
  json: {
    ...$('Normalize Ingest Trigger').item.json,
    jobId: $json.id,
  },
  pairedItem: { item: 0 },
}];

// Real self-serve Google Sheets: refreshes the token if expired,
// using Voxitron's own OAuth client credentials (env vars, not
// per-customer) against the customer's stored refresh_token.

const rows = $input.all();
if (rows.length === 0) {
  return [{ json: { result: 'No Google Sheet connected for this business yet.' } }];
}

const conn = rows[0].json;
let accessToken = conn.access_token;
const expiresAt = new Date(conn.expires_at);
const needsRefresh = expiresAt.getTime() < Date.now() + 60000; // refresh if expiring within a minute

try {
  if (needsRefresh) {
    const refreshResponse = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://oauth2.googleapis.com/token',
      body: {
        client_id: $env.GOOGLE_OAUTH_CLIENT_ID,
        client_secret: $env.GOOGLE_OAUTH_CLIENT_SECRET,
        refresh_token: conn.refresh_token,
        grant_type: 'refresh_token',
      },
      form: true,
      json: true,
    });

    accessToken = refreshResponse.access_token;
    const newExpiresAt = new Date(Date.now() + refreshResponse.expires_in * 1000).toISOString();

    // Save the refreshed token so the next call doesn't need to refresh again
    await this.helpers.httpRequestWithAuthentication.call(
      this, 'postgres',
      {} // placeholder -- real update: UPDATE customer_google_sheets_connections SET access_token=..., expires_at=... WHERE customer_id=...
    );
  }

  if (!conn.sheet_id) {
    return [{ json: { result: 'A Google account is connected, but no sheet has been picked yet.' } }];
  }

  const sheetResponse = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://sheets.googleapis.com/v4/spreadsheets/${conn.sheet_id}/values/A:Z`,
    headers: { Authorization: `Bearer ${accessToken}` },
    json: true,
  });

  const values = sheetResponse.values || [];
  if (values.length < 2) {
    return [{ json: { result: 'The connected sheet is empty.' } }];
  }

  const headers = values[0];
  const dataRows = values.slice(1);
  // One item per row, column names as keys -- exact shape Resolve
  // Content (Sheet) already expects, so that node needs no changes.
  return dataRows.map(row => ({
    json: Object.fromEntries(headers.map((h, i) => [h, row[i] || '']))
  }));

} catch (error) {
  return [{ json: { result: 'Having trouble reaching the connected sheet right now.' } }];
}

// ADDED 2026-09-02: Load Customer's Postgres output is just
// {id, business_name} -- same bug class as the earlier Create Ingest
// Job issue, just further downstream. Everything after this point that
// reads $json['Source Type'], $json['Content'], $json['Page URL'] etc.
// was silently getting undefined. Re-attaching the original fields
// here fixes every downstream node at once.

return [{
  json: {
    ...$('Normalize Ingest Trigger').item.json,
    id: $json.id,
    business_name: $json.business_name,
  },
  pairedItem: { item: 0 },
}];

// ADDED 2026-09-09: Fetch Webpage now uses fullResponse (needed to
// expose statusCode to Webpage Fetch OK? at all). That changes the
// output shape to {headers, statusCode, statusMessage, body} -- this
// restores the {data: ...} shape Extract Webpage Text already expects,
// so that node needs no changes.

return [{ json: { data: $json.body } }];

const MAX_PAGES = 20;
const MAX_DEPTH = 2;
const RELEVANCE_KEYWORDS = ['about', 'polic', 'faq', 'terms', 'privacy', 'shipping', 'return', 'contact', 'help', 'support'];

const seedUrl = $('Normalize Ingest Trigger').item.json['Page URL'];
let domain;
try {
  domain = new URL(seedUrl).hostname;
} catch (e) {
  return [{ json: { pageUrl: seedUrl, pageTitle: 'Invalid URL', pageText: '' } }];
}

function extractLinks(html, baseUrl) {
  const links = [];
  const regex = /<a\s+[^>]*href=["']([^"'#]+)["'][^>]*>([\s\S]*?)<\/a>/gi;
  let match;
  while ((match = regex.exec(html)) !== null) {
    try {
      const href = match[1];
      const text = match[2].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
      const absoluteUrl = new URL(href, baseUrl).toString().split('#')[0];
      links.push({ url: absoluteUrl, text });
    } catch (e) { /* skip malformed hrefs */ }
  }
  return links;
}

function extractTitle(html) {
  const match = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  return match ? match[1].trim() : 'Untitled Page';
}

function extractBodyText(html) {
  return html
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/\s+/g, ' ')
    .trim();
}

function isRelevant(url, text) {
  const combined = (url + ' ' + text).toLowerCase();
  return RELEVANCE_KEYWORDS.some(kw => combined.includes(kw));
}

const visited = new Set();
const queue = [{ url: seedUrl, depth: 0 }];
const pages = [];

while (queue.length > 0 && pages.length < MAX_PAGES) {
  const { url, depth } = queue.shift();
  if (visited.has(url)) continue;
  visited.add(url);

  let html;
  try {
    const response = await this.helpers.httpRequest({
      method: 'GET', url, returnFullResponse: true, timeout: 10000,
    });
    if (response.statusCode !== 200) continue;
    html = response.body;
  } catch (error) {
    continue; // one page failing shouldn't stop the whole crawl
  }

  pages.push({ url, title: extractTitle(html), text: extractBodyText(html) });

  if (depth < MAX_DEPTH) {
    for (const link of extractLinks(html, url)) {
      try {
        if (new URL(link.url).hostname !== domain) continue;
        if (visited.has(link.url)) continue;
        if (isRelevant(link.url, link.text)) {
          queue.push({ url: link.url, depth: depth + 1 });
        }
      } catch (e) { continue; }
    }
  }
}

if (pages.length === 0) {
  // Zero pages means the seed URL itself was unreachable -- returning an
  // empty array here would silently produce zero items all the way
  // downstream, leaving the job stuck as 'processing' forever instead of
  // ever failing visibly. Throwing surfaces it as a real, visible error.
  throw new Error(`Could not fetch anything starting from ${seedUrl} -- check the URL is correct and reachable.`);
}

return pages.map(p => ({ json: { pageUrl: p.url, pageTitle: p.title, pageText: p.text } }));
